/// Lookup only known symbolic defaults; no computed style is materialized eagerly.
#[must_use]
pub fn lookup(name: &str) -> Option<PropertyData> {
    ROWS.binary_search_by_key(&name, |row| row.0)
        .ok()
        .map(|index| PropertyData {
            initial: ROWS[index].1,
            inherited: ROWS[index].2,
        })
}

/// Canonical lookup rows, sorted by exact property name.
#[must_use]
